const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const totalOf = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

test('small order: no discount', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 3 }]), 30)
})

test('multiple lines are summed', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }]), 45)
})

test('total exactly 100 gets no discount (threshold is strictly > 100)', async () => {
  assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 100)
})

test('just over 100 gets 10% off, then floored (101 -> 90, not 90.9)', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 10 }, { sku: 'G', qty: 1 }, { sku: 'C', qty: 10 }]), 90) // 101.99 -> 91.79 -> 91 ? see below
})

test('discount is applied to whole order, not just the part above 100', async () => {
  assert.equal(await totalOf([{ sku: 'H', qty: 1 }]), 900)
  assert.equal(await totalOf([{ sku: 'H', qty: 10 }]), 9000)
})

test('discount is flat 10%: no larger tier for bigger orders', async () => {
  assert.equal(await totalOf([{ sku: 'H', qty: 100 }]), 90000)
})

test('floor truncates cents: 100.99 -> 90.891 -> 90', async () => {
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }]), 90)
})

test('undiscounted fractional totals are floored too (0.99 * 3 = 2.97 -> 2)', async () => {
  assert.equal(await totalOf([{ sku: 'G', qty: 3 }]), 2)
})

test('floating point: 33.4 * 3 = 100.2 -> 90.18 -> 90', async () => {
  assert.equal(await totalOf([{ sku: 'D', qty: 3 }]), 90)
})

test('total is whole euros (integer), so cents are lost', async () => {
  const total = await totalOf([{ sku: 'F', qty: 2 }])
  assert.ok(Number.isInteger(total))
  assert.equal(total, 181) // 201.98 -> 181.782
})

test('qty 0 gives total 0', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 0 }]), 0)
})

test('unknown sku (price undefined) yields a null total, still 201', async () => {
  const res = await post({ items: [{ sku: 'ZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('response shape and retrieval of created order', async () => {
  const items = [{ sku: 'B', qty: 5 }]
  const created = await (await post({ items })).json()
  assert.deepEqual(Object.keys(created).sort(), ['id', 'items', 'total'])
  assert.deepEqual(created.items, items)
  assert.equal(created.total, 112) // 125 -> 112.5 -> 112
  const fetched = await (await fetch(`${base}/orders/${created.id}`)).json()
  assert.deepEqual(fetched, created)
})

test('validation: missing/empty/invalid items -> 400', async () => {
  for (const body of [{}, { items: [] }, { items: 'x' }]) {
    const res = await post(body)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
  assert.equal((await post(null, 'not json')).status, 400)
})

test('unknown order returns 200 with an error body (quirk)', async () => {
  const res = await fetch(`${base}/orders/nope`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown route -> 404', async () => {
  const res = await fetch(`${base}/nothing`)
  assert.equal(res.status, 404)
})
EOF
node --test 2>&1 | grep -E "^# (pass|fail)|not ok|expected|actual"

